CREATE TABLE IF NOT EXISTS mutation_idempotency_tombstones (
  id INTEGER PRIMARY KEY,
  client_key_hash TEXT NOT NULL CHECK(length(client_key_hash) = 64 AND client_key_hash NOT GLOB '*[^0-9a-f]*'),
  ledger_uuid TEXT NOT NULL REFERENCES ledger_identity(ledger_uuid),
  operation TEXT NOT NULL CHECK(length(operation) BETWEEN 1 AND 256),
  principal_kind TEXT NOT NULL CHECK(principal_kind IN ('user','service-account')),
  principal_subject_id TEXT NOT NULL CHECK(length(principal_subject_id) BETWEEN 1 AND 256),
  payload_hash TEXT NOT NULL CHECK(length(payload_hash) = 64 AND payload_hash NOT GLOB '*[^0-9a-f]*'),
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  UNIQUE(client_key_hash, ledger_uuid, operation, principal_kind, principal_subject_id)
);
CREATE TABLE IF NOT EXISTS mutation_idempotency_outcomes (
  tombstone_id INTEGER PRIMARY KEY REFERENCES mutation_idempotency_tombstones(id),
  outcome_json TEXT NOT NULL CHECK(length(outcome_json) <= 65536 AND json_valid(outcome_json)),
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_mutation_idempotency_tombstones_expiry ON mutation_idempotency_tombstones(expires_at);
CREATE TRIGGER IF NOT EXISTS mutation_idempotency_tombstones_no_update BEFORE UPDATE ON mutation_idempotency_tombstones BEGIN SELECT RAISE(ABORT, 'idempotency tombstones are immutable'); END;
CREATE TRIGGER IF NOT EXISTS mutation_idempotency_tombstones_no_delete BEFORE DELETE ON mutation_idempotency_tombstones BEGIN SELECT RAISE(ABORT, 'idempotency tombstones are append-only'); END;
